const cd=document.getElementById('cd');if(cd){setInterval(()=>{const d=new Date(cd.dataset.date)-new Date();cd.textContent=d<=0?'Hari Tari Nasional dimulai!':Math.floor(d/86400000)+' hari '+Math.floor((d%86400000)/3600000)+' jam';},1000)}
for(let i=0;i<36;i++){const p=document.createElement('span');p.className='particle';p.style.left=Math.random()*100+'%';p.style.animationDelay=(Math.random()*12)+'s';p.style.opacity=Math.random();document.getElementById('particles')?.appendChild(p)}
const mapInfo=document.getElementById('map-info');document.querySelectorAll('.prov').forEach(p=>p.onclick=()=>mapInfo.textContent='Provinsi '+p.dataset.name+': tari khas siap dijelajahi.');
const s=document.getElementById('search');if(s){s.addEventListener('input',async()=>{const r=await fetch('?r=tari_ajax&q='+encodeURIComponent(s.value));const d=await r.json();document.getElementById('tari-list').innerHTML=d.map(x=>`<div class='col-md-3'><div class='card sky mb-3'><img loading='lazy' src='${x.gambar}' class='card-img-top'><div class='card-body'><h6>${x.nama_tari}</h6><small>${x.provinsi} • ${x.kategori}</small></div></div></div>`).join('')})}
const regions={Sumatera:['Tari Saman','Enerjik kolosal','https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=900&q=70'],Jawa:['Tari Serimpi','Elegan keraton','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=900&q=70'],Kalimantan:['Tari Hudoq','Nuansa ritual Dayak','https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=900&q=70'],Sulawesi:['Tari Pakarena','Gerak anggun','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=900&q=70'],Bali:['Tari Kecak','Dramatik vokal','https://images.unsplash.com/photo-1537996194471-e657df975ab4?auto=format&fit=crop&w=900&q=70'],Papua:['Tari Yospan','Semangat persaudaraan','https://images.unsplash.com/photo-1526779259212-756e1705ebb3?auto=format&fit=crop&w=900&q=70']};
document.querySelectorAll('#regionTabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('#regionTabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');const r=regions[b.dataset.r];document.getElementById('regionPreview').innerHTML=`<h4>${b.dataset.r}</h4><p>${r[0]} • ${r[1]}</p><img loading='lazy' src='${r[2]}' class='img-fluid rounded'><a href='#tari' class='btn btn-cyan mt-3'>Lihat Detail</a>`});
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('show')}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
document.querySelectorAll('[data-count]').forEach(el=>{let done=false;const run=()=>{if(done)return;done=true;let n=0,t=+el.dataset.count;const step=Math.max(1,Math.floor(t/60));const tick=()=>{n+=step;el.textContent=n>=t?t+'+':n; if(n<t)requestAnimationFrame(tick)};tick()};new IntersectionObserver(es=>es.forEach(e=>e.isIntersecting&&run()),{threshold:.5}).observe(el)});
const audio=document.getElementById('bgAudio'),btn=document.getElementById('audioToggle');btn?.addEventListener('click',()=>{if(audio.paused){audio.play();btn.textContent='🔇 Mute'}else{audio.pause();btn.textContent='🔈 Musik'}});
